import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // --- extract config ---
  const {
    imageUrl,
    textContent,
    scenePlacement = { position: [0, 1, 0.06], rotation: [0, 0, 0], scale: [1, 1, 1] },
    // atlasRegion is ignored for background texture, font atlas uses its own
  } = config;

  const pos = new THREE.Vector3(...scenePlacement.position);
  const rot = new THREE.Euler(...scenePlacement.rotation);
  const scl = new THREE.Vector3(...scenePlacement.scale);

  // --- load texture (synchronous cached) ---
  const texture = ctx.textureLoader.load(imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // --- background plane ---
  const bgGeo = new THREE.PlaneGeometry(1.2, 0.35);
  const bgMat = new THREE.MeshBasicNodeMaterial({
    map: texture,
    color: new THREE.Color('#16161d'), // ink tone for deep base
    transparent: true,
  });
  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.z = 0;

  // --- text using font atlas ---
  let textMesh = null;
  if (textContent && ctx.fontAtlas && ctx.fontAtlas.createText) {
    // assume textContent is an array or string
    const textStr = Array.isArray(textContent)
      ? textContent[0]?.text || 'Collection 2'
      : textContent;
    const textOpts = {
      font: 'Lora',
      fontSize: 39,
      fontWeight: 400,
      color: '#e8ecf2', // paper color for readability
    };
    textMesh = ctx.fontAtlas.createText(textStr, textOpts);
    // center text on the plane
    textMesh.position.set(0, 0, 0.001);
  }

  // --- group ---
  const group = new THREE.Group();
  group.add(bgMesh);
  if (textMesh) group.add(textMesh);

  group.position.copy(pos);
  group.rotation.copy(rot);
  group.scale.copy(scl);

  // --- event handlers (none) ---
  group.userData.handlers = {};

  // --- cleanup ---
  group.userData.cleanup = () => {
    bgGeo.dispose();
    bgMat.dispose();
    texture.dispose();
    if (textMesh) {
      textMesh.geometry?.dispose();
      textMesh.material?.dispose();
    }
    // kill any gsap timelines on this group
    gsap.killTweensOf(group);
    group.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        child.material?.dispose();
      }
    });
  };

  return group;
}
